function validate(input) {
  const [val, method, other] = input;
  if (method !== 'toBe' && method !== 'notToBe') return 'method must be "toBe" or "notToBe".';
  for (const value of [val, other]) {
    if (value === undefined) return 'val and other must be JSON values.';
    if (JSON.stringify(value).length > 1000) return 'Keep val and other under 1,000 characters of JSON each.';
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [val, method, other] = input;
  const show = value => (value === undefined ? 'undefined' : JSON.stringify(value));
  const expectation = solve(val);
  if (!expectation || typeof expectation.toBe !== 'function' || typeof expectation.notToBe !== 'function') {
    throw new Error('expect must return an object with toBe and notToBe methods.');
  }
  kit.trace(`expect(${show(val)}).${method}(${show(other)}) is called`);
  try {
    const value = expectation[method](other);
    kit.trace(`${method} returns ${show(value)}`);
    return { value: value === undefined ? null : value };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    kit.trace(`${method} throws "${message}"`);
    return { error: message };
  }
}

