function expect(val) {
  class Expectation {
    toBe(other) {
      if ([val].includes(other)) return true;
      throw new Error('Not Equal');
    }
    notToBe(other) {
      if ([val].includes(other)) throw new Error('Equal');
      return true;
    }
  }
  return new Expectation();
}

