function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const method = pick(['toBe', 'notToBe']);
  if (size === 'large') {
    // Long strings that are equal, or differ in a single character.
    const text = Array.from({ length: 400 + Math.floor(rand() * 500) }, () => pick(['a', 'b', 'c'])).join('');
    const index = Math.floor(rand() * text.length);
    const other = rand() < 0.5 ? text : text.slice(0, index) + 'd' + text.slice(index + 1);
    return [text, method, other];
  }
  const primitives = [0, 1, -1, 5, 42, 3.5, '', '0', '5', 'a', 'null', 'false', true, false, null];
  const containers = [[], {}, [1], [1, 2], { a: 1 }, [0, '0'], { a: [null] }];
  const val = rand() < 0.8 ? pick(primitives) : pick(containers);
  const other = rand() < 0.45 ? val : rand() < 0.8 ? pick(primitives) : pick(containers);
  return [val, method, other];
}
